        var result = Run(new AccountState(5, 0), stock, null, new Operation.Deposit(new NoteCounts(0, 1, 0)), out var d);

        Assert.Equal(new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, new AccountState(25, 0)), result);
