        public bool Dispense(NoteCounts notes)
        {
            Passes.Add(notes);
            if (Passes.Count == FailDispenseOnPass || notes.Total is < 1 or > 4)
            {
                return false;
            }

            Stock -= notes;
            return true;
        }

        public bool Load(NoteCounts notes)
        {
            if (FailLoad)
            {
                return false;
            }

            Stock += notes;
            return true;
        }
    }
